import {
  Sprite,
  SpriteMaterial,
  TextureLoader,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const ASSET_URL = config.imageUrl; // '/prism-assets/chrome/ceramic-grain.map.png'
  const ASPECT = 512 / 320; // atlas region width / height

  // Create sprite material – will be updated with texture when loaded
  const material = new SpriteMaterial({
    transparent: true,
    depthWrite: false,
  });

  // Create sprite with aspect-ratio scale
  const sprite = new Sprite(material);
  sprite.scale.set(1, 1 / ASPECT, 1);

  // Load texture asynchronously and apply atlas region
  ctx.textureLoader.loadTexture(ASSET_URL).then((tex) => {
    const srcW = 512;
    const srcH = 320;
    const texW = tex.image.width;
    const texH = tex.image.height;
    tex.offset.set(0, 0);
    tex.repeat.set(srcW / texW, srcH / texH);
    material.map = tex;
    material.needsUpdate = true;
  });

  // Attach cleanup handler
  sprite.userData.cleanup = () => {
    material.dispose();
    if (material.map) material.map.dispose();
  };

  // No primitives, no handlers, no GSAP timelines
  sprite.userData.handlers = {};

  return sprite;
}
